bool TlOutbox::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    else
    {
        err="The id column cannot be null";
        return false;
    }
    if(pJson.isMember("tenant_id"))
    {
        if(!validJsonOfField(1, "tenant_id", pJson["tenant_id"], err, true))
            return false;
    }
    else
    {
        err="The tenant_id column cannot be null";
        return false;
    }
    if(pJson.isMember("aggregate_type"))
    {
        if(!validJsonOfField(2, "aggregate_type", pJson["aggregate_type"], err, true))
            return false;
    }
    else
    {
        err="The aggregate_type column cannot be null";
        return false;
    }
    if(pJson.isMember("aggregate_id"))
    {
        if(!validJsonOfField(3, "aggregate_id", pJson["aggregate_id"], err, true))
            return false;
    }
    else
    {
        err="The aggregate_id column cannot be null";
        return false;
    }
    if(pJson.isMember("event_type"))
    {
        if(!validJsonOfField(4, "event_type", pJson["event_type"], err, true))
            return false;
    }
    else
    {
        err="The event_type column cannot be null";
        return false;
    }
    if(pJson.isMember("payload"))
    {
        if(!validJsonOfField(5, "payload", pJson["payload"], err, true))
            return false;
    }
    if(pJson.isMember("request_id"))
    {
        if(!validJsonOfField(6, "request_id", pJson["request_id"], err, true))
            return false;
    }
    if(pJson.isMember("actor_user_id"))
    {
        if(!validJsonOfField(7, "actor_user_id", pJson["actor_user_id"], err, true))
            return false;
    }
    if(pJson.isMember("occurred_at"))
    {
        if(!validJsonOfField(8, "occurred_at", pJson["occurred_at"], err, true))
            return false;
    }
    if(pJson.isMember("published_at"))
    {
        if(!validJsonOfField(9, "published_at", pJson["published_at"], err, true))
            return false;
    }
    return true;
}
